#include <cstring>
#include <cstdlib>
#include <cstdio>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>

// Microservice: session token validator behind nginx reverse proxy
// Receives X-Forwarded-For and session tokens from proxy

static const int MAX_HEADER_SIZE = 4096;
static const int MAX_SESSIONS = 256;
static const char* TRUSTED_PROXY = "127.0.0.1";

struct SessionEntry {
    char token[64];
    char username[32];
    unsigned long expires;
    unsigned int privileges;
};

static SessionEntry session_table[MAX_SESSIONS];
static int session_count = 0;

struct RequestContext {
    char method[16];
    char path[256];
    char forwarded_for[64];
    char auth_token[64];
    char body[512];
    int content_length;
};

// Parse chunked transfer encoding from proxy
int parse_chunked_body(int fd, char* output, int max_len) {
    char chunk_header[32];
    int total = 0;
    while (total < max_len) {
        int i = 0;
        char c;
        while (i < 31 && read(fd, &c, 1) == 1 && c != '\n') {
            chunk_header[i++] = c;
        }
        chunk_header[i] = '\0';
        int chunk_size = (int)strtol(chunk_header, NULL, 16);
        if (chunk_size == 0) break;
        if (total + chunk_size > max_len) chunk_size = max_len - total;
        int rd = read(fd, output + total, chunk_size);
        if (rd <= 0) break;
        total += rd;
        read(fd, &c, 1); // \r
        read(fd, &c, 1); // \n
    }
    output[total] = '\0';
    return total;
}

// Validate session token - returns privilege level
int validate_session(const char* token) {
    for (int i = 0; i < session_count; i++) {
        if (strncmp(session_table[i].token, token, 63) == 0) {
            return session_table[i].privileges;
        }
    }
    return -1;
}

// Process admin command - only callable with privilege >= 2
void process_admin_command(const char* cmd, int cmd_len, char* response, int resp_size) {
    // Stack buffer for command assembly with strict bounds
    char assembled[128];
    // Enforce strict size limit regardless of transfer encoding
    int safe_len = cmd_len < 127 ? cmd_len : 127;
    memcpy(assembled, cmd, safe_len);
    assembled[safe_len] = '\0';

    if (strncmp(assembled, "status", 6) == 0) {
        snprintf(response, resp_size, "OK: %d sessions active", session_count);
    } else if (strncmp(assembled, "flush", 5) == 0) {
        session_count = 0;
        snprintf(response, resp_size, "OK: sessions flushed");
    } else {
        snprintf(response, resp_size, "ERR: unknown command");
    }
}

void handle_request(int client_fd, struct sockaddr_in* peer) {
    // Only accept from trusted proxy
    char peer_ip[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &peer->sin_addr, peer_ip, sizeof(peer_ip));
    if (strcmp(peer_ip, TRUSTED_PROXY) != 0) {
        const char* resp = "HTTP/1.1 403 Forbidden\r\n\r\n";
        write(client_fd, resp, strlen(resp));
        return;
    }

    char headers[MAX_HEADER_SIZE];
    int hdr_len = 0;
    char prev[4] = {0};

    // Read headers until \r\n\r\n
    while (hdr_len < MAX_HEADER_SIZE - 1) {
        char c;
        if (read(client_fd, &c, 1) != 1) break;
        headers[hdr_len++] = c;
        prev[0] = prev[1]; prev[1] = prev[2]; prev[2] = prev[3]; prev[3] = c;
        if (prev[0]=='\r' && prev[1]=='\n' && prev[2]=='\r' && prev[3]=='\n') break;
    }
    headers[hdr_len] = '\0';

    RequestContext ctx;
    memset(&ctx, 0, sizeof(ctx));

    // Parse method and path
    sscanf(headers, "%15s %255s", ctx.method, ctx.path);

    // Extract X-Forwarded-For
    char* xff = strstr(headers, "X-Forwarded-For:");
    if (xff) sscanf(xff + 16, " %63s", ctx.forwarded_for);

    // Extract Authorization token
    char* auth = strstr(headers, "Authorization: Bearer ");
    if (auth) sscanf(auth + 22, "%63s", ctx.auth_token);

    // Check for chunked transfer encoding
    int is_chunked = (strstr(headers, "Transfer-Encoding: chunked") != NULL);

    // Extract Content-Length
    char* cl = strstr(headers, "Content-Length:");
    if (cl) ctx.content_length = atoi(cl + 15);

    // Read body
    int body_len = 0;
    if (is_chunked) {
        body_len = parse_chunked_body(client_fd, ctx.body, sizeof(ctx.body) - 1);
    } else if (ctx.content_length > 0) {
        int to_read = ctx.content_length;
        if (to_read > (int)sizeof(ctx.body) - 1) to_read = sizeof(ctx.body) - 1;
        body_len = read(client_fd, ctx.body, to_read);
        if (body_len > 0) ctx.body[body_len] = '\0';
    }

    // Route: POST /admin/cmd requires privilege >= 2
    if (strcmp(ctx.method, "POST") == 0 && strcmp(ctx.path, "/admin/cmd") == 0) {
        int priv = validate_session(ctx.auth_token);
        if (priv < 2) {
            const char* resp = "HTTP/1.1 401 Unauthorized\r\n\r\n";
            write(client_fd, resp, strlen(resp));
            return;
        }
        char response[256];
        process_admin_command(ctx.body, body_len, response, sizeof(response));
        char http_resp[512];
        snprintf(http_resp, sizeof(http_resp),
            "HTTP/1.1 200 OK\r\nContent-Length: %zu\r\n\r\n%s",
            strlen(response), response);
        write(client_fd, http_resp, strlen(http_resp));
    } else {
        const char* resp = "HTTP/1.1 404 Not Found\r\n\r\n";
        write(client_fd, resp, strlen(resp));
    }
}

int main() {
    signal(SIGPIPE, SIG_IGN);

    // Pre-populate a test session
    strcpy(session_table[0].token, "admin-token-abc123");
    strcpy(session_table[0].username, "admin");
    session_table[0].privileges = 3;
    session_count = 1;

    int srv = socket(AF_INET, SOCK_STREAM, 0);
    int opt = 1;
    setsockopt(srv, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr;
    addr.sin_family = AF_INET;
    addr.sin_port = htons(8081);
    addr.sin_addr.s_addr = inet_addr("127.0.0.1");

    bind(srv, (struct sockaddr*)&addr, sizeof(addr));
    listen(srv, 16);

    while (1) {
        struct sockaddr_in peer;
        socklen_t peer_len = sizeof(peer);
        int client = accept(srv, (struct sockaddr*)&peer, &peer_len);
        if (client < 0) continue;
        handle_request(client, &peer);
        close(client);
    }
    return 0;
}
